          'ระดับที่สามคือ Procedures (ขั้นตอนปฏิบัติ) ซึ่งอธิบายทีละขั้นว่า "ต้องลงมือทำอย่างไร" (Step-by-step How-to) เพื่อให้บรรลุ Policy และ Standard อย่างสม่ำเสมอ ไม่ว่าจะเปลี่ยนคนทำงานกี่คนผลลัพธ์ก็ยังคงเดิม เช่น ขั้นตอนการสร้างบัญชีพนักงานใหม่หรือวิธีตัดสิทธิ์เมื่อลาออก ส่วนระดับที่สี่คือ Guidelines (แนวทางปฏิบัติ) ซึ่งเป็นข้อแนะนำหรือ Best Practices ที่ "ควรทำ" แต่ไม่ได้บังคับตายตัว (Non-mandatory) เรามักใช้ Guideline เมื่อเทคโนโลยีนั้นยังไม่มีมาตรฐานบังคับเฉพาะทาง หรือเมื่อต้องการให้ทีมผู้เชี่ยวชาญมีความยืดหยุ่นในการปรับใช้ให้เหมาะกับงานเฉพาะหน้า'
