          'นอกจากนี้ยังมีนโยบายเฉพาะด้านสำหรับความต่อเนื่องและการเปลี่ยนแปลง ได้แก่ Business Continuity (BC) Policy ที่มุ่งรักษากระบวนการธุรกิจสำคัญให้เดินหน้าต่อไปได้ระหว่างวิกฤต (ครอบคลุมคน สถานที่ และกระบวนการธุรกิจ) ซึ่งต่างจาก Disaster Recovery (DR) Policy ที่มุ่งเน้นการกู้คืนระบบไอที โครงสร้างพื้นฐาน และข้อมูลหลังเกิดภัยพิบัติให้กลับมาทำงานได้ตามเป้าหมาย ตามด้วย Incident Response (IR) Policy ที่กำหนดอำนาจหน้าที่ในการรับมือเหตุละเมิดความปลอดภัย Secure Software Development Lifecycle (SDLC) Policy ที่บังคับให้ฝังความปลอดภัยตั้งแต่การออกแบบโค้ดจนถึงการทดสอบก่อนขึ้นระบบจริง และ Change Management Policy ที่บังคับให้ทุกการเปลี่ยนแปลงระบบต้องได้รับการประเมินความเสี่ยงและอนุมัติล่วงหน้า',
