        contentTh: [
          'Phishing Campaigns (แคมเปญจำลองฟิชชิง) คือการส่งอีเมลทดสอบที่จำลองกลยุทธ์ของผู้โจมตีจริงไปยังพนักงานภายในองค์กรอย่างปลอดภัยและได้รับอนุญาต เพื่อให้พนักงานได้ฝึกทักษะในสถานการณ์เสมือนจริงและช่วยให้ทีมความปลอดภัยวัดระดับความเสี่ยงของแต่ละแผนกได้แม่นยำ แต่แคมเปญที่ดีต้องสร้างความตื่นตัว ไม่ใช่สร้างความเกลียดชัง ดังนั้นเนื้อหาจำลองไม่ควรล่อลวงด้วยเรื่องส่วนตัวที่กระทบจิตใจรุนแรงเกินควร และเมื่อพนักงานคลิกควรแสดงหน้าจอสอนความรู้สั้นๆ ทันที (Just-in-time Training)',
          'หัวใจสำคัญที่ต้องฝึกให้ผู้ใช้จดจำได้แม่นยำคือ Recognizing a Phishing Attempt (การสังเกตสัญญาณเตือนอีเมลหลอกลวง) ได้แก่ ชื่อโดเมนผู้ส่งที่สะกดคล้ายของจริง (Typosquatting เช่น `company-support.com` แทน `company.com`), ความขัดแย้งระหว่าง Display Name กับที่อยู่อีเมลจริง, ความพยายามสร้างความตื่นตระหนกหรือเร่งด่วนผิดปกติ ("บัญชีจะถูกระงับภายใน 1 ชั่วโมง"), การใช้คำทักทายกว้างๆ ไม่ระบุตัวตน, ลิงก์ปลายทางที่ปรากฏเมื่อเลื่อนเมาส์ไปชี้ (Hover) ไม่ตรงกับข้อความที่แสดง และไฟล์แนบที่ผิดปกติ (เช่น ไฟล์ `.html`, `.iso` หรือเอกสารที่ขอให้เปิด Macro)',
          'องค์ประกอบที่มักถูกมองข้ามแต่มีความสำคัญเท่าเทียมกันคือ Responding to Reported Suspicious Messages เมื่อองค์กรติดตั้งปุ่ม "Report Phishing" และฝึกให้พนักงานกดรายงานทันทีที่สงสัย ทีม SOC จะต้องมีกระบวนการตอบสนองที่รวดเร็ว ได้แก่ 1) คัดแยกและวิเคราะห์อีเมล (ตรวจ Email Header, SPF/DKIM/DMARC, URL และไฟล์แนบใน Sandbox) 2) หากพบว่าเป็นอันตรายจริง ให้ค้นหาและลบอีเมลแบบเดียวกันออกจากกล่องจดหมายของพนักงานคนอื่นทั้งหมด (Purge) พร้อมบล็อกผู้ส่งและลิงก์ที่ Email Gateway ทันที และ 3) ส่งข้อความยืนยันและขอบคุณกลับไปยังพนักงานผู้แจ้งอย่างรวดเร็ว เพื่อเสริมแรงทางบวกให้พนักงานกล้ารายงานต่อไปแม้บางครั้งจะเป็นอีเมลปกติ (False Positive)'
        ],
