        titleTh: '4. หัวข้อฝึกอบรมหลัก: User Guidance, Removable Media/Cables, OPSEC และ Hybrid/Remote Work',
        contentTh: [
          'SY0-701 Objective 5.6 ระบุหัวข้อ User Guidance and Training ที่องค์กรต้องสื่อสารให้ครอบคลุม เริ่มจาก Policy and Handbooks ที่สรุปนโยบายเช่น AUP ให้เป็นคู่มือภาษาคนอ่านง่าย, Situational Awareness ที่ฝึกให้พนักงานสังเกตสภาพแวดล้อมรอบตัว เช่น ไม่อนุญาตให้คนแปลกหน้าเดินตามหลังเข้าประตูคีย์การ์ด (Tailgating) และระวังการแอบมองหน้าจอ (Shoulder Surfing) ในที่สาธารณะ, Insider Threat ที่สอนให้พนักงานรู้จักสัญญาณความเสี่ยงและช่องทางแจ้งเบาะแสอย่างปลอดภัย และ Password Management ที่ส่งเสริมการใช้รหัสผ่านที่ยาวไม่ซ้ำกัน การใช้ Password Manager และการเปิด MFA ทุกบัญชี',
          'หัวข้อทางกายภาพและเทคนิคใกล้ตัวที่พนักงานมักพลาดคือ Removable Media and Cables พนักงานต้องเข้าใจว่าห้ามเสียบ USB Drive ที่เก็บได้หรือได้รับแจกฟรีเข้าคอมพิวเตอร์องค์กรเด็ดขาด เพราะอาจบรรจุมัลแวร์หรือวงจรคีย์บอร์ดจำลองที่รันคำสั่งโจมตีอัตโนมัติ ขณะเดียวกันสายชาร์จ USB และพอร์ตชาร์จสาธารณะในสนามบินหรือร้านกาแฟก็อาจถูกดัดแปลงเพื่อขโมยข้อมูลหรือฉีดโค้ด (Juice Jacking) ผู้ใช้จึงควรพกอะแดปเตอร์ปลั๊กไฟและ Power Bank ส่วนตัว หรือใช้สายชาร์จแบบจ่ายไฟอย่างเดียว (Power-only Cable) รวมถึงต้องฝึกอบรมต่อต้าน Social Engineering ทุกรูปแบบทั้ง Phishing, Vishing, Smishing และ Pretexting',
          'อีกสองหัวข้อสำคัญอย่างยิ่งในโลกการทำงานสมัยใหม่คือ Operational Security (OPSEC) และ Hybrid / Remote Work Environments สำหรับ OPSEC พนักงานต้องระมัดระวังไม่เปิดเผยข้อมูลการปฏิบัติงานโดยไม่ตั้งใจ เช่น ไม่ถ่ายภาพบัตรพนักงาน หน้าจอมอนิเตอร์ โต๊ะทำงาน หรือกระดานไวท์บอร์ดที่มีข้อมูลโครงการลับลงบนโซเชียลมีเดีย และไม่สนทนาเรื่องช่องโหว่ ซอฟต์แวร์ที่ใช้ หรือแผนธุรกิจลับในร้านอาหารหรือลิฟต์ ส่วนแนวทาง Hybrid / Remote Work ต้องฝึกให้ผู้ใช้เชื่อมต่อ VPN ขององค์กรเสมอเมื่อทำงานนอกสำนักงาน ไม่ใช้คอมพิวเตอร์บริษัททำเรื่องส่วนตัว ตรวจสอบความปลอดภัย Wi-Fi ที่บ้าน (ใช้ WPA3 และเปลี่ยนรหัสผ่านเราเตอร์เริ่มต้น) ล็อกหน้าจอทุกครั้งที่ลุกจากโต๊ะ ใช้ฟิล์มกันแอบมอง (Privacy Screen) และระมัดระวังไม่ให้บุคคลในบ้านหรืออุปกรณ์ผู้ช่วยอัจฉริยะ (Smart Speakers) ได้ยินการประชุมความลับ'
        ],
